import{_ as n,a0 as i,w as p,s as m,ao as r,I as o,x as u,a1 as s,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"如何在Ubuntu桌面上使用Steam Music音乐播放器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu桌面上使用Steam Music音乐播放器 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu桌面上使用Steam Music音乐播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu桌面上使用Steam Music音乐播放器 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141008 How To Use Steam Music Player on Ubuntu Desktop","title":"如何在Ubuntu桌面上使用Steam Music音乐播放器","tag":"201412","desc":""},"relativePath":"201412/20141008 How To Use Steam Music Player on Ubuntu Desktop.md","filePath":"[post].md"}'),l={name:"201412/20141008 How To Use Steam Music Player on Ubuntu Desktop.md"};function g(c,t,d,w,b,S){const e=i("Link");return p(),m("div",null,[t[13]||(t[13]=r('<h1 id="如何在ubuntu桌面上使用steam-music音乐播放器" tabindex="-1">如何在Ubuntu桌面上使用Steam Music音乐播放器 <a class="header-anchor" href="#如何在ubuntu桌面上使用steam-music音乐播放器" aria-label="Permalink to “如何在Ubuntu桌面上使用Steam Music音乐播放器”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/steam-music.jpg" alt=""></p><p><strong>‘音乐让人们走到一起’ 麦当娜曾这样唱道。但是Steam的新音乐播放器特性能否很好的混搭小资与叛逆？</strong></p><p>如果你曾与世隔绝，充耳不闻，你就会错过与Steam Music的相识。它的特性并不是全新的。从今年的早些时候开始，它就已经以这样或那样的形式进行了测试。</p><p>但Steam客户端最近一次在Windows、Mac和Linux上的定期更新中，所有的客户端都能使用它了。你会问为什么一个游戏客户端会添加一个音乐播放器呢？当然是为了让你能一边玩游戏一边一边听你最喜欢的音乐了。</p><p>别担心：在游戏的音乐声中再加上你自己的音乐，听起来并不会像你想象的那么糟（哈哈）。Steam会帮你减少或消除游戏的背景音乐，但在混音器中保持效果音的高音量，以便于你能和平时一样听到那些叮，嘭和各种爆炸声。</p><h3 id="使用steam-music音乐播放器" tabindex="-1">使用Steam Music音乐播放器 <a class="header-anchor" href="#使用steam-music音乐播放器" aria-label="Permalink to “使用Steam Music音乐播放器”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-music-bpm.jpg" alt="Music in Big Picture Mode"></p><p><em>大图模式</em></p><p>任何使用最新版客户端的人都能使用Steam Music音乐播放器。它是个相当简单的附加程序：它让你能从你的电脑中添加、浏览并播放音乐。</p><p>播放器可以以两种方式进入：桌面和（超棒的）Steam大图模式。在两种方式下，控制播放都超级简单。</p><p>作为一个Rhythmbox的对手或是Spotify的继承者，把<strong>为玩游戏时放音乐而设计</strong>作为特点一点也不吸引人。事实上，他没有任何可购买音乐的商店，也没有整合Rdio，Grooveshark这类在线服务或是桌面服务。没错，你的多媒体键在Linux的播放器上完全不能用。</p><p>Valve说他们“<em>……计划增加更多的功能以便用户能以新的方式体验Steam Music。我们才刚刚开始。</em>”</p><h4 id="steam-music的重要特性" tabindex="-1">Steam Music的重要特性：#### <a class="header-anchor" href="#steam-music的重要特性" aria-label="Permalink to “Steam Music的重要特性：####”">​</a></h4><ul><li>只能播放MP3文件</li><li>与游戏中的音乐相融</li><li>在游戏中可以控制音乐</li><li>播放器可以在桌面上或在大图模式下运行</li><li>基于播放列表的播放方式</li></ul><p><strong>它没有整合到Ubuntu的声音菜单里，而且目前也不支持键盘上的多媒体键。</strong></p><h3 id="在ubuntu上使用steam-music播放器" tabindex="-1">在Ubuntu上使用Steam Music播放器 <a class="header-anchor" href="#在ubuntu上使用steam-music播放器" aria-label="Permalink to “在Ubuntu上使用Steam Music播放器”">​</a></h3><p>显然，添加音乐是你播放音乐前的第一件事。在Ubuntu上，默认设置下，Steam会自动添加两个文件夹：Home下的标准Music目录和它自带的Steam Music文件夹。任何可下载的音轨都保存在其中。</p><p>注意：目前<strong>Steam Music只能播放MP3文件</strong>。如果你的大部分音乐都是其他文件格式（比如.acc、.m4a等等），这些文件不会被添加也不能被播放。</p><p>若想添加其他的文件夹或重新扫描：</p><ul><li>到<strong>View &gt; Settings &gt; Music</strong>。</li><li>点击‘<strong>Add</strong>‘将其他位置的文件夹添加到已列出两个文件夹的列表下。</li><li>点击‘<strong>Start Scanning</strong>’</li></ul><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/Tardis.jpg" alt=""></p><p>你还可以在这个对话框中调整其他设置，包括‘scan at start’。如果你经常添加新音乐而且很容易忘记手动启动扫描，请标记此项。你还可以选择当路径变化时是否显示提示，设置默认的音量，还能调整当你打开一个应用软件或语音聊天时的播放状态的改变。</p><p>一旦你的音乐源成功的被添加并扫描后，你就可以通过主客户端的<strong>Library &gt; Music</strong>区域浏览你的音乐了。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/09/browser.jpg" alt=""></p><p>Steam Music会默认的将音乐按照专辑进行分组。若想按照乐队名进行浏览，你需要点击‘Albums’然后从下拉菜单中选择‘Artists’。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-selection.jpg" alt=""></p><p>Steam Music是一个以‘队列’方式工作的系统。你可以通过双击浏览器里的音乐或右键单击并选择‘Add to Queue’来把音乐添加到播放队列里。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-music-queue.jpg" alt=""></p><p>若想<strong>启动桌面播放器</strong>请点击右上角的音符图标或通过<strong>View &gt; Music Player</strong>菜单。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/steam-music.jpg" alt=""></p><hr>',32)),o("p",null,[t[1]||(t[1]=u("via: ",-1)),s(e,{href:"http://www.omgubuntu.co.uk/2014/10/use-steam-music-player-linux"},{default:a(()=>[...t[0]||(t[0]=[u("http://www.omgubuntu.co.uk/2014/10/use-steam-music-player-linux",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=u("作者：",-1)),s(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[2]||(t[2]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[6]||(t[6]=u(" 译者：",-1)),s(e,{href:"https://github.com/H-mudcup"},{default:a(()=>[...t[3]||(t[3]=[u("H-mudcup",-1)])]),_:1}),t[7]||(t[7]=u(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[u("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=u("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[u("LCTT",-1)])]),_:1}),t[11]||(t[11]=u(" 原创翻译，",-1)),s(e,{href:"http://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[u("Linux中国",-1)])]),_:1}),t[12]||(t[12]=u(" 荣誉推出",-1))])])}const f=n(l,[["render",g]]);export{h as __pageData,f as default};
